// Mashed RE — port-state seed (PORT-STATE-02, decision L-99 (a)). Exe only (the .asi runs inside MASHED.exe, which
// already carries these bytes). PREREG: verify/portstate_20261108/PREREG_PORT-STATE-02.md.
//
// The exe's image pad (exe_main.cpp B17, g_b17_low_arena_pad) spans the original's address range zero-filled, so
// a matched body that reads a file-backed .rdata / .data value of the original reads 0 here. PortStateSeed.inc
// (generated by re/tools/gen_portstate_seed.py from original/MASHED.exe.unpatched, anchor BDCAE093...3C0E) holds
// exactly the addresses of the PORT-STATE-01 inventory (verify/portstate_20261108/SEED_CANDIDATES.tsv). With
// default ON since L-101 (Mariano 2026-11-08), WinMain copies it into the pad before anything else runs.
// MASHED_NO_PORTSTATE_SEED=1 opts out: nothing is written and nothing is logged (the pad stays zero-filled).
//
// Refusal: the table's FNV-1a is recomputed from its own arrays before any write; a mismatch writes nothing.
// Every entry must lie inside the pad (checked per entry; an entry outside is skipped and counted).

#include "PortStateSeed.h"

#include <cstdio>
#include <cstring>
#include <windows.h>

#include "PortStateSeed.inc"

extern "C" char g_b17_low_arena_pad[0x00A00000];   // exe_main.cpp B17

namespace mashed_re {
namespace Compat {
namespace {

std::uint32_t FnvStep(std::uint32_t h, const unsigned char* p, std::size_t n) {
    for (std::size_t i = 0; i < n; ++i) { h ^= p[i]; h *= 16777619u; }
    return h;
}

std::uint32_t FnvEntries(bool fromMemory) {
    std::uint32_t h = 2166136261u;
    for (const PortStateSeedEntry& e : kPortStateSeedEntries) {
        unsigned char hdr[8];
        std::memcpy(hdr, &e.addr, 4);
        std::memcpy(hdr + 4, &e.len, 4);
        h = FnvStep(h, hdr, 8);
        const unsigned char* src = fromMemory ? reinterpret_cast<const unsigned char*>(static_cast<std::uintptr_t>(e.addr))
                                              : kPortStateSeedData + e.off;
        h = FnvStep(h, src, e.len);
    }
    return h;
}

bool     s_applied   = false;
unsigned s_written   = 0;
unsigned s_bytes     = 0;
unsigned s_outside   = 0;
bool     s_fnvBad    = false;
std::uint32_t s_fnvTable = 0;

} // namespace

bool PortStateSeed_On() {
    static const bool s_on = (GetEnvironmentVariableA("MASHED_NO_PORTSTATE_SEED", nullptr, 0) == 0);   // L-101: default ON
    return s_on;
}

unsigned PortStateSeed_Apply() {
    if (!PortStateSeed_On() || s_applied) return 0;
    s_applied = true;
    s_fnvTable = FnvEntries(false);
    if (s_fnvTable != MASHED_PORTSTATE_SEED_FNV1A) { s_fnvBad = true; return 0; }
    const std::uintptr_t lo = reinterpret_cast<std::uintptr_t>(&g_b17_low_arena_pad[0]);
    const std::uintptr_t hi = lo + sizeof(g_b17_low_arena_pad);
    for (const PortStateSeedEntry& e : kPortStateSeedEntries) {
        const std::uintptr_t a = e.addr;
        if (a < lo || a + e.len > hi) { ++s_outside; continue; }
        std::memcpy(reinterpret_cast<void*>(a), kPortStateSeedData + e.off, e.len);
        ++s_written;
        s_bytes += e.len;
    }
    return s_written;
}

void PortStateSeed_Log(const char* logPath) {
    if (!PortStateSeed_On() || !s_applied) return;   // IMG-2-LOADER: not applied = the image ran in its place
    std::FILE* f = std::fopen(logPath, "a");
    if (!f) return;
    std::fprintf(f, "[portstate-seed] on entries=%u/%u bytes=%u/%u outside_pad=%u fnv table=%08x want=%08x mem=%08x%s\n",
                 s_written, static_cast<unsigned>(MASHED_PORTSTATE_SEED_ENTRIES), s_bytes,
                 static_cast<unsigned>(MASHED_PORTSTATE_SEED_BYTES), s_outside, s_fnvTable,
                 static_cast<unsigned>(MASHED_PORTSTATE_SEED_FNV1A),
                 (s_written == MASHED_PORTSTATE_SEED_ENTRIES) ? FnvEntries(true) : 0u,
                 s_fnvBad ? " REFUSED(fnv)" : "");
    std::fclose(f);
}

} // namespace Compat
} // namespace mashed_re
